from itertools import combinations
feats={'1':np.ones_like(t),'lnA':np.log(A),'t':t,'lnt':np.log(t),'1/t':1/t,'A':A,'t2':t**2,'lnA*t':np.log(A)*t,'A^2':A**2,'1/A':1/A,'tA':t*A,'sqrtA':np.sqrt(A),'sqrtt':np.sqrt(t)}
names=list(feats)
best=[]
for k in [2,3,4]:
  for c in combinations([n for n in names if n!='1'],k-0):
    cols=['1']+list(c) if '1' not in c else list(c)
    X=np.column_stack([feats[n] for n in cols])
    for target,tn in [(dA_dt,'lin'),(np.log(-dA_dt),'log')]:
      if tn=='log': 
        b=np.linalg.lstsq(X,target,rcond=None)[0]; p=np.exp(X@b); p=-p
      else:
        b=np.linalg.lstsq(X,target,rcond=None)[0]; p=X@b
      r=np.mean((dA_dt-p)**2)/np.var(dA_dt)
      best.append((r,tn,cols))
best.sort(key=lambda z:z[0])
for z in best[:8]: print(z)

